import os
from collections import defaultdict
from itertools import chain
import json

import attr
import mozpack.path as mozpath


ROLLOUTS_HEADER = """/*
 * This file is automatically generated by mozlint. Do not modify it manually.
 *
 * This lists existing linting errors that are ignored as new linting rules are
 * being rolled out. You should only be updating this file when enabling a new
 * rule.
 */
"""


class ResultSummary:
    """Represents overall result state from an entire lint run."""

    root = None

    def __init__(self, root, fail_on_warnings=True):
        self.fail_on_warnings = fail_on_warnings
        self.reset()

        # Store the repository root folder to be able to build
        # Issues relative paths to that folder
        if ResultSummary.root is None:
            ResultSummary.root = mozpath.normpath(root)

    def reset(self):
        self.issues = defaultdict(list)
        self.failed_run = set()
        self.failed_setup = set()
        self.skipped = set()
        self.suppressed_warnings = defaultdict(int)
        self.fixed = 0

    def has_issues_failure(self):
        """Returns true in case issues were detected during the lint run. Do not
        consider warning issues in case `self.fail_on_warnings` is set to False.
        """
        if self.fail_on_warnings is False:
            return any(
                result.level != "warning" for result in chain(*self.issues.values())
            )
        return len(self.issues) >= 1

    def load_rollouts(self):
        path = os.path.join(ResultSummary.root, "lint-rollouts.json")
        if os.path.exists(path):
            with open(path, "r") as f:
                # The JSON parser doesn't support comments so strip the leading comment.
                contents = f.read().lstrip()
                if contents.startswith("/*"):
                    _, separator, contents = contents.partition("*/")
                    if not separator:
                        raise ValueError(
                            "Unterminated leading comment in lint-rollouts.json"
                        )
                return json.loads(contents)
        else:
            return dict()

    def save_rollouts(self, rollouts):
        path = os.path.join(ResultSummary.root, "lint-rollouts.json")
        with open(path, "w") as f:
            f.write(ROLLOUTS_HEADER)
            json.dump(rollouts, f, indent=2, sort_keys=True)
            f.write("\n")

    def strip_rollouts(self, linters):
        all_linters = len(linters) == 0
        rollouts = self.load_rollouts()

        for path, issues in list(self.issues.items()):
            relpath = mozpath.relpath(path, ResultSummary.root)

            # Lazy load the file
            file_contents = None

            for issue in list(issues):
                # We can only strip errors with a rule and line number
                if issue.rule is None or issue.lineno is None or issue.level != "error":
                    continue

                # If this rule is not listed in the rollouts or there are no
                # cases of that rule for this file then do nothing
                if (
                    issue.linter not in rollouts
                    or issue.rule not in rollouts[issue.linter]
                    or relpath not in rollouts[issue.linter][issue.rule]
                ):
                    continue

                ignored_lines = rollouts[issue.linter][issue.rule][relpath]

                if file_contents is None:
                    with open(issue.path, "r") as f:
                        file_contents = f.readlines()

                bad_line = file_contents[issue.lineno - 1].strip()
                if bad_line in ignored_lines:
                    ignored_lines[bad_line] -= 1
                    issues.remove(issue)

            if len(issues) == 0:
                del self.issues[path]

        linter_changes = set()
        rule_changes = set()

        for linter, linter_rollouts in rollouts.items():
            if not all_linters and linter not in linters:
                continue

            for rule, rule_rollouts in linter_rollouts.items():
                for relpath, ignored_lines in rule_rollouts.items():
                    for count in ignored_lines.values():
                        if count > 0:
                            linter_changes.add(linter)
                            rule_changes.add(rule)
                            break

        if len(rule_changes) > 0:
            linter_args = ["-l " + l for l in linter_changes]
            rule_args = ["--update-rollouts " + r for r in rule_changes]
            print(
                "Ignored lint errors have been fixed. Please run ./mach lint "
                + " ".join(linter_args)
                + " "
                + " ".join(rule_args)
                + " ."
            )

    # rules is an array of rule names or True to indicate all rules
    # linters is an array of linter names or an empty array when running all linters
    def update_rollouts(self, rules, linters):
        all_rules = True in rules
        all_linters = len(linters) == 0

        if all_rules and all_linters:
            rollouts = dict()
        else:
            rollouts = self.load_rollouts()

            # First remove any existing entries for the chosen linters and rules
            for linter, linter_rollouts in list(rollouts.items()):
                if not (all_linters or linter in linters):
                    continue

                for rule, rule_rollouts in list(linter_rollouts.items()):
                    if all_rules or rule in rules:
                        del linter_rollouts[rule]

                if len(linter_rollouts) == 0:
                    del rollouts[linter]

        for issues in self.issues.values():
            # Lazy load the file
            file_contents = None

            for issue in issues:
                if (
                    not (all_rules or issue.rule in rules)
                    or issue.lineno is None
                    or issue.level != "error"
                ):
                    continue

                linter_rollouts = rollouts.setdefault(issue.linter, dict())
                rule_rollouts = linter_rollouts.setdefault(issue.rule, dict())
                ignored_lines = rule_rollouts.setdefault(issue.relpath, dict())

                if file_contents is None:
                    with open(issue.path, "r") as f:
                        file_contents = f.readlines()

                bad_line = file_contents[issue.lineno - 1].strip()
                if bad_line in ignored_lines:
                    ignored_lines[bad_line] += 1
                else:
                    ignored_lines[bad_line] = 1

        self.save_rollouts(rollouts)

    @property
    def returncode(self):
        if self.has_issues_failure() or self.failed:
            return 1
        return 0

    @property
    def failed(self):
        return self.failed_setup | self.failed_run

    @property
    def total_issues(self):
        return sum([len(v) for v in self.issues.values()])

    @property
    def total_suppressed_warnings(self):
        return sum(self.suppressed_warnings.values())

    @property
    def total_fixed(self):
        return self.fixed

    def update(self, other):
        """Merge results from another ResultSummary into this one."""
        for path, obj in other.issues.items():
            self.issues[path].extend(obj)

        self.failed_run |= other.failed_run
        self.failed_setup |= other.failed_setup
        self.skipped |= other.skipped
        self.fixed += other.fixed
        for k, v in other.suppressed_warnings.items():
            self.suppressed_warnings[k] += v


@attr.s(slots=True, kw_only=True)
class Issue:
    """Represents a single lint issue and its related metadata.

    :param linter: name of the linter that flagged this error
    :param path: path to the file containing the error
    :param message: text describing the error
    :param lineno: line number that contains the error
    :param column: column containing the error
    :param level: severity of the error, either 'warning' or 'error' (default 'error')
    :param hint: suggestion for fixing the error (optional)
    :param source: source code context of the error (optional)
    :param rule: name of the rule that was violated (optional)
    :param lineoffset: denotes an error spans multiple lines, of the form
                       (<lineno offset>, <num lines>) (optional)
    :param diff: a diff describing the changes that need to be made to the code
    """

    linter = attr.ib()
    path = attr.ib()
    lineno = attr.ib(
        default=None, converter=lambda lineno: int(lineno) if lineno else 0
    )
    column = attr.ib(
        default=None, converter=lambda column: int(column) if column else column
    )
    message = attr.ib()
    hint = attr.ib(default=None)
    source = attr.ib(default=None)
    level = attr.ib(default=None, converter=lambda level: level or "error")
    rule = attr.ib(default=None)
    lineoffset = attr.ib(default=None)
    diff = attr.ib(default=None)
    relpath = attr.ib(init=False, default=None)

    def __attrs_post_init__(self):
        root = ResultSummary.root
        assert root is not None, "Missing ResultSummary.root"
        if os.path.isabs(self.path):
            self.path = mozpath.normpath(self.path)
            self.relpath = mozpath.relpath(self.path, root)
        else:
            self.relpath = mozpath.normpath(self.path)
            self.path = mozpath.join(root, self.path)


class IssueEncoder(json.JSONEncoder):
    """Class for encoding :class:`~result.Issue` to json.

    Usage:

    .. code-block:: python

        json.dumps(results, cls=IssueEncoder)

    """

    def default(self, o):
        if isinstance(o, Issue):
            return attr.asdict(o)
        return JSONEncoder.default(self, o)


def from_config(config, **kwargs):
    """Create a :class:`~result.Issue` from a linter config.

    Convenience method that pulls defaults from a linter
    config and forwards them.

    :param config: linter config as defined in a .yml file
    :param kwargs: same as :class:`~result.Issue`
    :returns: :class:`~result.Issue` object
    """
    args = {}
    for arg in attr.fields(Issue):
        if arg.init:
            args[arg.name] = kwargs.get(arg.name, config.get(arg.name))

    if not args["linter"]:
        args["linter"] = config.get("name")

    if not args["message"]:
        args["message"] = config.get("description")

    return Issue(**args)
